const rl = readline.createInterface({ input: process.stdin, terminal: false });
let inputLines = [];
rl.on('line', (line) => {
    inputLines.push(line.trim());
});
rl.on('close', () => {
    main(inputLines[0]);
});

const vis = [];
for (let i = 0; i < 110; i++) {
    vis.push(new Array(110).fill(1));
}

const f = [[0, 1], [1, 0], [0, -1], [-1, 0]];

class PriorityQueue {
    constructor() {
        this.heap = [];
    }
    push(node) {
        this.heap.push(node);
        this.heap.sort((a, b) => a.step - b.step);
    }
    pop() {
        return this.heap.shift();
    }
    top() {
        return this.heap[0];
    }
    empty() {
        return this.heap.length === 0;
    }
}

function bfs(l, u, xi, yi) {
    const q = new PriorityQueue();
    let e = { x: l, y: u, step: 0 };
    q.push(e);
    vis[e.x][e.y] = 1;
    while (!q.empty()) {
        e = q.pop();
        if (e.x === xi && e.y === yi) return e.step;
        for (let i = 0; i < 4; i++) {
            let t = {
                x: e.x + f[i][0],
                y: e.y + f[i][1],
                step: e.step + 1
            };
            if (t.x < 0 || t.y < 0) continue;
            if (vis[t.x][t.y]) continue;
            vis[t.x][t.y] = 1;
            q.push(t);
        }
    }
    return -1;
}

function main(s) {
    let len = s.length;
    let x = 0, y = 0, xx = 0, yy = 0;
    for (let i = 0; i < len; i++) {
        if (s[i] === 'L') y--;
        if (s[i] === 'R') y++;
        if (s[i] === 'U') x--;
        if (s[i] === 'D') x++;
        xx = Math.min(xx, x);
        yy = Math.min(yy, y);
    }
    xx = -xx;
    yy = -yy;

    for (let i = 0; i < 110; i++) {
        for (let j = 0; j < 110; j++) {
            vis[i][j] = 1;
        }
    }

    x = xx;
    y = yy;
    for (let i = 0; i < len; i++) {
        if (s[i] === 'L') y--;
        if (s[i] === 'R') y++;
        if (s[i] === 'U') x--;
        if (s[i] === 'D') x++;
        vis[x][y] = 0;
    }

    let ans = bfs(xx, yy, x, y);

    if (ans === len) {
        console.log("OK");
    } else {
        console.log("BUG");
    }
}
